import{_ as i,l as o,o as r,c as s,v as E,p as d,x as n,d as t,i as p,S as B,b as e}from"./chunks/framework.InCnrqk-.js";const x=JSON.parse('{"title":"北交所与新三板","description":"","frontmatter":{"title":"北交所与新三板","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/cn-bse-neeq.md","filePath":"quant/cn-bse-neeq.md","lastUpdated":1789023840000}'),h={name:"quant/cn-bse-neeq.md"};function u(A,a,c,m,f,b){const l=o("Mermaid");return r(),s("div",null,[a[1]||(a[1]=E('<h1 id="北交所与新三板" tabindex="-1">北交所与新三板 <a class="header-anchor" href="#北交所与新三板" aria-label="Permalink to &quot;北交所与新三板&quot;">​</a></h1><div class="epigraph"><p>北交所从新三板精选层而来，投资者适当性、涨跌幅、竞价与信息披露与沪深主板不是同一套参数。把精选层历史直接并进全 A 因子，门槛与流动性会错。</p><footer>—— 北京证券交易所交易规则及相关适当性规定；全国中小企业股份转让系统分层与转让规则；对照[科创板/创业板](/quant/star-chinext)</footer></div><p><a href="/quant/cn-convertible-market">上一课</a>仍在沪深产品。本课的缺口是<strong>另一交易所层级</strong>：新三板基础层/创新层的协议与做市转让，以及 2021 年设立的北京证券交易所（由精选层平移）。涨跌幅、最小申报、适当性、连续竞价时段与沪深不同。后课注册制主要写沪深 IPO，但北交所也是注册制试点的一支，本课先钉交易与宇宙。不把北交所股票画进沪深<a href="/quant/lob-structure">LOB</a> 当同一深度。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>全 A 研究常以沪深为样本。北交所股票代码、指数（如北证 50）与投资者门槛（相对沪深更高的资产与经验要求，以现行适当性为准）使订单流更机构化或更稀疏——两者都可能，取决于阶段，须用数据而不是口号。问题是：因子宇宙是否包含北交所、从哪一日起（开板日 vs 精选层历史）、流动性过滤如何设。用沪深 10% 涨跌停去套北交所 30% 日常涨跌幅（以规则为准），锁定概率与磁吸全部错。</p><p>新三板非北交所层级仍可能是协议转让或做市，价格形成不是连续双向拍卖的同一状态机。把做市成交当竞价中间价，价差与冲击模型失效。样本应分转让方式。</p><h3 id="历史拼接" tabindex="-1">历史拼接 <a class="header-anchor" href="#历史拼接" aria-label="Permalink to &quot;历史拼接&quot;">​</a></h3><p>精选层公司平移北交所，法律主体连续，交易规则切换。回测应在切换日分段：精选层规则 vs 北交所规则。用北交所现行规则回填精选层，属于制度前视。发行与再融资、做市转竞价，都是状态变量。</p><p><span class="marginnote">北向沪深港通不包含北交所。外资与互连通因子不要把北证成分当可买。指数增强的基准若不含北证，偏离进北证是主动风险。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>主数据：市场层级、转让方式、涨跌幅版本、适当性类别、最小申报单位。组合：客户达不到适当性则权重强制为零。流动性：用成交天数、价差、是否连续竞价过滤，而不是只按市值。与沪深因子比较时报告「含北证 / 不含北证」两套，避免一个显著结果来自十来只小样本。</p><p>停牌、信息披露与摘牌规则不同，退市收益处理要单独实现，不能直接套 CRSP Shumway 的数字，只能套其原则：退出价格必须记账。</p><h3 id="指数与-etf" tabindex="-1">指数与 ETF <a class="header-anchor" href="#指数与-etf" aria-label="Permalink to &quot;指数与 ETF&quot;">​</a></h3><p>北证 50 等指数的编制与调仓冲击在薄市场上更大。ETF 若存在，申赎篮子流动性可能弱于沪深 300ETF，折溢价与冲击见 ETF 课，参数重估。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>适当性提高门槛，减少噪声交易者，也可能减少风险分担，使波动与价差在薄市场更大。涨跌幅更宽降低锁定频率，但单日跳空可以更大，T+1 仍限制回转（以北交所交易规则为准）。因子的换手与反转在此样本上可能改号，属于另一市场，不是「全 A 的稳健性检验」。</p><p>新三板做市：深度来自做市商库存，撤出做市会瞬时改变可成交性，类似国际做市市场，而不是沪深竞价。</p>',17)),(r(),d(B,null,{default:n(()=>[p(l,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20NEEQ%5B%22%E6%96%B0%E4%B8%89%E6%9D%BF%20%E5%88%86%E5%B1%82%E8%BD%AC%E8%AE%A9%22%5D%20--%3E%20BSE%5B%22%E5%8C%97%E4%BA%A4%E6%89%80%20%E7%AB%9E%E4%BB%B7%22%5D%0A%20%20BSE%20--%3E%20Univ%5B%22%E6%98%AF%E5%90%A6%E8%BF%9B%E5%85%A5%E7%A0%94%E7%A9%B6%E5%AE%87%E5%AE%99%22%5D%0A%20%20Suit%5B%22%E9%80%82%E5%BD%93%E6%80%A7%E9%97%A8%E6%A7%9B%22%5D%20--%3E%20Univ%0A%20%20Limit%5B%22%E6%B6%A8%E8%B7%8C%E5%B9%85%E4%B8%8E%E7%94%B3%E6%8A%A5%E5%8D%95%E4%BD%8D%22%5D%20--%3E%20Micro%5B%22%E5%8F%A6%E4%B8%80%E5%A5%97%E5%BE%AE%E8%A7%82%E7%BB%93%E6%9E%84%E5%8F%82%E6%95%B0%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e("h2",{id:"边界",tabindex:"-1"},[t("边界 "),e("a",{class:"header-anchor",href:"#边界","aria-label":'Permalink to "边界"'},"​")],-1)),a[3]||(a[3]=e("p",null,"不提供规避适当性或利用分层信息优势损害普通投资者的方法。老三板、退市板块另算。本课不评估「专精特新」叙事的投资价值，只写规则如何进状态机。",-1)),a[4]||(a[4]=e("h2",{id:"小结",tabindex:"-1"},[t("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[5]||(a[5]=e("ul",null,[e("li",null,"北交所与新三板不是沪深主板的小市值子集；适当性、涨跌幅、转让方式须单列。"),e("li",null,"精选层到北交所要分段；港股通不可及。"),e("li",null,"因子稳健性应分样本报告，避免小样本驱动。"),e("li",null,"出处：北交所交易规则；股转系统分层与转让规则。")],-1))])}const D=i(h,[["render",u]]);export{x as __pageData,D as default};
